document.addEventListener("DOMContentLoaded",function(){const e=document.querySelectorAll(".job-duration");e.forEach(e=>{const n=e.dataset.start,t=e.dataset.end;if(!n)return;const[a,r]=n.split("-").map(Number);let s,o;if(t==="present"){const e=new Date;s=e.getFullYear(),o=e.getMonth()+1}else[s,o]=t.split("-").map(Number);const c=calculateDuration(a,r,s,o),l=t==="present"?"present":t;e.textContent=`${n} ~ ${l}`;const i=document.createElement("span");i.className="entry__duration",i.textContent=`(${c})`,e.appendChild(i)})});function calculateDuration(e,t,n,s){const i=(n-e)*12+(s-t)+1,a=Math.floor(i/12),r=i%12;let o="";return a>0&&(o+=`${a}年`),r>0&&(o+=`${r}ヶ月`),o||"0ヶ月"}